def link_existing_donations(apps, schema_editor):
    """Every donor already typed on a donation becomes a saved donor."""
    Donor = apps.get_model('library', 'Donor')
    Donation = apps.get_model('library', 'Donation')
    by_name = {}
    for donation in Donation.objects.all():
        clean = ' '.join((donation.donor_name or '').split())
        if not clean:
            continue
        key = clean.lower()
        if key not in by_name:
            by_name[key] = Donor.objects.create(name=clean)
        donation.donor = by_name[key]
        donation.save(update_fields=['donor'])


